  return (
    <div className="s-page">
      <h1 className="s-page-title">Báº£ng Ä‘iá»ƒm</h1>
      <p className="s-page-sub">Káº¿t quáº£ há»c táº­p cá»§a báº¡n</p>
      {loading ? <div className="s-loading">Äang táº£i...</div> :
        grades.length === 0 ? (
