function timeAgo(d) {
  if (!d) return '';
  const s = Math.floor((Date.now()-new Date(d))/1000);
  if (s < 60) return 'Vá»«a xong';
  if (s < 3600) return `${Math.floor(s/60)} phÃºt trÆ°á»›c`;
  if (s < 86400) return `${Math.floor(s/3600)} giá» trÆ°á»›c`;
  return `${Math.floor(s/86400)} ngÃ y trÆ°á»›c`;
}

export function StudentNotifications({ onRead }) {
  const [notifications, setNotifications] = useState([]);
  const [unread, setUnread] = useState(0);
  const [loading, setLoading] = useState(true);

  const fetch = async () => {
    try {
      const r = await axios.get(`${API}/student/notifications`);
      setNotifications(r.data.notifications || []);
      setUnread(r.data.unread || 0);
    } catch {} finally { setLoading(false); }
  };

  useEffect(() => { fetch(); }, []);

  const readAll = async () => {
    await axios.put(`${API}/student/notifications/read-all`).catch(()=>{});
    fetch(); onRead?.();
  };

  return (
    <div className="s-page">
      <div className="s-noti-header">
        <div>
          <h1 className="s-page-title">ThÃ´ng bÃ¡o</h1>
          <p className="s-page-sub">{unread > 0 ? `${unread} thÃ´ng bÃ¡o chÆ°a Ä‘á»c` : 'ÄÃ£ Ä‘á»c háº¿t'}</p>
        </div>
        {unread > 0 && <button className="s-btn-read-all" onClick={readAll}>âœ“ ÄÃ¡nh dáº¥u Ä‘Ã£ Ä‘á»c</button>}
      </div>
      {loading ? <div className="s-loading">Äang táº£i...</div> :
        notifications.length === 0 ? (
          <div className="s-empty-state"><div className="s-empty-icon">ðŸ””</div><div>ChÆ°a cÃ³ thÃ´ng bÃ¡o</div></div>
        ) : (
          <div className="s-noti-list">
            {notifications.map(n => (
              <div key={n.id} className={`s-noti-card ${!n.is_read ? 'unread' : ''}`}>
                <div className="s-noti-icon">ðŸ””</div>
                <div className="s-noti-body">
                  <div className="s-noti-title">{n.title}</div>
                  <div className="s-noti-msg">{n.message}</div>
                  {n.sender_name && <div className="s-noti-sender">ðŸ‘¤ {n.sender_name}</div>}
                  <div className="s-noti-time">{timeAgo(n.created_at)}</div>
                </div>
                {!n.is_read && <div className="s-noti-dot"></div>}
              </div>
            ))}
          </div>
        )
      }
    </div>
  );
}
